-- Sovietski: the SU-40 Thunderspear anti-aircraft tank and the SU-45 Earthquake medium battle tank (printed 192-197).
-- 2 vehicle rows, with 28 locations and 9 weapon entries.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~390-sovietski-v5.sql
--
-- Written by scripts/vessel-sql.mjs from 1 worker file(s). Every value
-- is printable ASCII, every row cites its book, and a Main Body location
-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('su-40-thunderspear', 'SU-40 Thunderspear Anti-Aircraft Tank', 'rifts', 'vehicle', 'Four: a Tank Commander, a Tank Driver, a Tank Specialist and a gunner.', 'None.', '70 mph (112 km) top, 45 mph (72 km) off-road. Range effectively unlimited.', 'None.', 'Not amphibious; wades in water as deep as 4 feet (1.2 m) with no trouble.', 'Height 12 feet (3.7 m) counting the radar dome; width 11 feet (3.4 m), length 16 feet (4.9 m).', '26 tons fully loaded', 335, 1, NULL, 26000000, '26 million credits. Built for the Sovietski alone; it is not sold on the Black Market.', 'A self-propelled anti-aircraft gun. The Sovietski leans on conventional armor and cyborgs rather than airborne power armor, so its ground columns needed cover against low flyers: Warlord Wing Riders, Gargoyles, and Brodkil or cyborgs that fly. The answer, modeled on a pre-Rifts flak tank, is a medium tank chassis whose turret has been swapped for four fire-linked flak cannons and an early warning radar tuned to pick up incoming missiles and small airborne targets. The turret turns a full 360 degrees and the guns elevate 80 degrees up or down, so they can shoot nearly straight overhead. A short-range missile launcher rides on each side of the turret, and a light pulse laser on the hull gives the crew something to fight with when the flak runs short. The top hatch sits so low it can be hit only by an enemy standing over it; a second hatch in the floor lets the crew drop out under the tank, and most foes, demons especially, have no idea it is there. Cargo: three lockers, each with a rifle, a sidearm, a canteen, two rocket flares and Red Star body armor; the crew also carries a week of rations and one gallon (3.8 liters) of water. Nuclear, 20-year average life. Standard Sovietski vehicle systems, plus an enhanced radar that tracks up to 144 targets at once out to 300 miles (480 km).', 'Rifts World Book 36: Sovietski p.192-194'),
  ('su-45-earthquake', 'SU-45 Earthquake Medium Battle Tank', 'rifts', 'vehicle', 'Five: a Tank Commander, a Tank Driver, a Tank Specialist and two gunners.', 'Four jump seats just inside the rear hatch.', '90 mph (144 km) top, 60 mph (96 km) cruising, 45 mph (72 km) off-road. Range effectively unlimited. The EarthARK bridge-layer is 25% slower.', 'None.', 'Not amphibious; wades in water as deep as 4.5 feet (1.4 m) with no trouble.', 'Height 10 feet (3 m); width 12 feet (3.7 m), length 26 feet (7.9 m).', '22 tons; the EarthARK with its bridge adds 12 tons', 390, 1, NULL, 27400000, '27.4 million credits, Sovietski military only and not on the Black Market. Knock-off copies exist but are rarely built; a captured one in good shape fetches about 22 to 30 million credits.', 'A flexible medium tank seen everywhere in Sovietski territory and on every kind of ground, used as mobile armored artillery, to back up infantry and to press sieges. What marks it at a glance is the newest Sovietski plasma cannon in its turret, and it hits hard. Against demons that shrug off energy, the crew turns to the secondary weapons: an 85 mm solid slug auto-cannon that takes any of the special tank rounds, and mini-missiles. Two medium lasers on folding robot arms at the rear tuck into the hull when idle and unfold to cover any direction, including the deck and turret. A ram prow up front clears wrecks and debris and bowls over troops. The SU-45b EarthARK variant keeps the chassis and secondary weapons but trades the turret for a folding hydraulic bridge 80 feet (24 m) long that bears 100 tons, letting infantry, tanks and lighter vehicles get over creeks, ravines, collapsed bridges or mud; the bridge uncouples once laid, the ARK crosses on it, then hooks it back up and folds it on the far bank. While carrying the bridge the ARK can fire only the auto-cannon and the two rear lasers. Two spare treads are carried; a trained crew fits one in the field in 1D4x10+30 minutes, an untrained one in twice that. Cargo: 4 tons, in a pair of storage compartments just inside the rear hatch used to run supplies where a normal supply line cannot reach, plus a crew-compartment locker for five backpacks and basic gear. Nuclear, 20-year life. Standard Sovietski vehicle features, plus a front spotlight on the hull that turns 360 degrees and tilts 45 degrees up or down, reaching 600 feet (183 m).', 'Rifts World Book 36: Sovietski p.194-197');

