INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('su-40-thunderspear', 1, 'Anti-Aircraft Flak Guns (4)', 'One round: 4D6 M.D. to a 20 foot (6.1 m) blast radius. Two rounds: 1D4x10 M.D. All four guns: 2D4x10 M.D. over a 60 foot (18.3 m) aerial blast radius.', 1, '12,000 feet (3,658 m)', 'A single shot, a pair or a four-gun blast each uses one of the gunner''s melee attacks.', '2,000 rounds per gun from an internal magazine, enough for 500 four-gun blasts.', NULL, 'Four fire-linked guns in the turret, worked by a dedicated gunner; they fire singly, in pairs or all together, at one target or to fill a patch of sky. Turret turns 360 degrees, guns elevate 80 degrees up and down. Gargoyles and many flying Lesser Demons, Archaic Russian Demons among them, are rattled by a flak barrage: -3 on Perception Rolls, -2 on initiative, and -1 to strike, to dodge and to Horror Factor. Anti-aircraft and anti-flying creature, then anti-missile and defense.'),
  ('su-40-thunderspear', 2, 'Short-Range Missile Launchers (2)', 'Varies with the missile; usually 8 high explosive (medium: 2D6x10 M.D. to a 15 foot/4.6 m radius), 8 fragmentation (2D4x10 M.D. to a 20 foot/6.1 m radius) and two smoke', 1, 'High explosive 5 miles (8 km); fragmentation 3 miles (4.8 km)', 'One at a time or volleys of 2, 3, 4 or 6.', '18, nine per launcher.', NULL, 'One launcher on each side of the turret, able to swing through 180 degrees to aim forward, straight up or to the rear. Fired by the Tank Commander or the gunner, mostly at flying targets. Anti-flyer and assault, then anti-missile and defense.'),
  ('su-40-thunderspear', 3, 'Low-Profile Light Pulse Laser Turret', '4D6 M.D. per triple pulse; bursts only', 1, '2,000 feet (610 m)', 'Each triple burst uses one melee attack.', 'Effectively unlimited.', NULL, 'On the hull front, worked by the Tank Driver against infantry and light vehicles. It swings through 180 degrees horizontally and 45 degrees vertically. Defense, then anti-personnel.'),
  ('su-45-earthquake', 1, 'SPC-90 Heavy Plasma Cannon', '1D6x10+10 M.D. per blast', 1, '4,000 feet (1,219 m)', 'Each blast uses one melee attack; unlike the Maelstrom''s cannon it needs no cooling period.', 'Effectively unlimited.', NULL, 'The turret''s main gun, worked by a dedicated gunner seated in the turret. The turret turns 360 degrees with a 60 degree up and down arc. Assault and artillery support, then anti-armor and anti-monster.'),
  ('su-45-earthquake', 2, 'STG-34 Auto-Cannon', 'Standard rounds: solid slug (may be silver-coated) 4D6 M.D., or high explosive 5D6 M.D. to a 2 foot (0.6 m) blast radius. Armor piercing (5D6 M.D.) and wood (2D6 M.D.) rounds may be issued on assignment.', 1, '4,000 feet (1,219 m)', 'Single shots only; each uses one melee attack.', '1,200 rounds.', '+1 to strike', 'On the right side of the hull, with an autoloader that chambers the next shell the moment one is fired, and able to fire every special tank slug round in the book. Faces forward with a 30 degree up and down arc; fired by the Tank Driver or the Tank Commander. Anti-armor and anti-monster, then assault and defense.'),
  ('su-45-earthquake', 3, 'Rear-Mounted Laser Weapon Arms (2)', '3D6 M.D. per single blast (the book omits the unit here), 6D6 M.D. when both fire at one target together; only 1D6 M.D. against enemies climbing onto the tank from behind', 1, '2,500 feet (762 m)', 'Each burst uses one melee attack.', 'Effectively unlimited.', NULL, 'A pair of medium lasers on robot arms that fold into a housing in the hull when not needed. Unfolded, each turns 360 degrees, swings forward or back and can rise to cover the flanks, the deck and the turret top as well as front and rear. The Tank Specialist or a gunner of their own works them. Anti-personnel, then defense.'),
  ('su-45-earthquake', 4, 'Mini-Missile Launcher', 'Varies with the missile; the standard load is 7 high explosive (5D6 M.D. to a 5 foot/1.5 m blast radius), 7 plasma (1D6x10 M.D.) and 2 smoke, though any mini-missile fits. For non-lethal city assaults and riot work: 8 tear gas, 5 smoke and 2 high explosive for breaching barriers or doors.', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3 or 4.', '16.', NULL, 'In the turret beneath the plasma cannon, fired by the turret gunner instead of the cannon or between its blasts. The book points to page 363 of Rifts Ultimate Edition for other missile types. Anti-personnel, then assault.'),
  ('su-45-earthquake', 5, 'Smoke Dispensers (8)', NULL, 0, 'A dense cloud covering a 40 foot (12.2 m) area behind the tank, or the tank itself when it is stopped.', NULL, 'Eight: six smoke and two tear gas.', NULL, 'Four units on each side of the turret; they can release tear gas as well as smoke.'),
  ('su-45-earthquake', 6, 'Ram Prow', '1D6 M.D. per 10 mph (16 km) of speed; a humanoid under 22 feet (6.7 m) tall has a 01-80% chance of being knocked down, losing initiative and one melee attack', 1, 'Contact: a ram.', NULL, NULL, NULL, 'Shoves parked, stalled or wrecked vehicles and debris aside, breaks through light fortifications and knocks down infantry, cyborgs, Shocktroopers, Brodkil and giant monsters. The prow takes 10% of the damage when it rams something big and heavy (a Superheavy Machine, a Warlord Shocktrooper, an armored vehicle, a giant robot, a Gargoyle, a wall or a fortification), and neither prow nor tank takes any from crowds, Light Machines, Brodkil, fences, barbed wire, cars or car-sized debris.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 machines are in' AS assertion, count(*) AS got, 2 AS want
  FROM vehicles WHERE slug IN ('su-40-thunderspear', 'su-45-earthquake');
SELECT 'their 28 locations are in' AS assertion, count(*) AS got, 28 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('su-40-thunderspear', 'su-45-earthquake');
SELECT 'their 9 weapon entries are in' AS assertion, count(*) AS got, 9 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('su-40-thunderspear', 'su-45-earthquake');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('su-40-thunderspear', 'su-45-earthquake') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

